export const authFile = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

export const SUBTITLE_NO_LINK = 'מלאו את פרטי העסק — הלקוח יישמר ברשימת הלקוחות.';
export const SUBTITLE_LINK = 'מלאו את פרטי העסק — ייווצר קישור הצטרפות שתמסרו ללקוח.';
