/** Строка клиента в списке /customers (кнопка-строка с «פעולות»). */
export const rowOf = (page: Page, name: string) =>
  page.getByRole('button').filter({ hasText: name }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).first();

export async function openList(page: Page) {
  await page.goto('/customers');
  await expect(page.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(/^מציג \d+–\d+ מתוך /)).toBeVisible({ timeout: 30_000 });
}

/** Сузить список поиском по имени (список admin разбит на страницы по 8). */
export async function search(page: Page, name: string) {
  await page.getByPlaceholder('חיפוש לקוח לפי שם עסק או איש קשר').fill(name);
}

export async function openNewCustomer(page: Page) {
  await page.getByRole('button', { name: 'לקוח חדש' }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'לקוח חדש' })).toBeVisible();
  return dlg;
}

/** REST (PostgREST) от сессии текущей страницы: ключ из бандла, токен из localStorage. */
export async function rest(page: Page, method: string, q: string, body?: unknown) {
  return page.evaluate(
    async ({ method, q, body }) => {
      const w = window as unknown as { __qaKey?: string };
      if (!w.__qaKey) {
        for (const src of [...document.scripts].map((s) => s.src).filter(Boolean)) {
          const t = await (await fetch(src)).text();
          const m = t.match(/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/);
          if (m) { w.__qaKey = m[0]; break; }
        }
      }
      const key = w.__qaKey!;
      const tokenKey = Object.keys(localStorage).find((k) => k.includes('auth-token'))!;
      const token = JSON.parse(localStorage.getItem(tokenKey)!).access_token;
      const ref = JSON.parse(atob(key.split('.')[1])).ref as string;
      const r = await fetch(`https://${ref}.supabase.co/rest/v1/${q}`, {
        method,
        headers: { apikey: key, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', Prefer: 'return=representation' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      const text = await r.text();
      let json: unknown = null;
      try { json = JSON.parse(text); } catch { /* not json */ }
      return { status: r.status, json: json as any };
    },
    { method, q, body },
  );
}

/**
 * Чистка: admin удаляет через UI (⋮ → «מחיקה») всех клиентов, чьё имя начинается с prefix.
 * Клиенты без заказов удаляются полностью; проверяется, что в REST их больше нет.
 */
export async function deleteCustomersByPrefix(browser: Browser, baseURL: string | undefined, prefix: string) {
  const ctx = await browser.newContext({ storageState: authFile('admin'), baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  try {
    await openList(page);
    // если сессия admin осталась в «כניסה כעובד» — вернуться в аккаунт админа
    const back = page.getByText('חזרה לחשבון הניהול');
    if (await back.count()) {
      await back.click();
      await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
      await openList(page);
    }
    const found = await rest(page, 'GET', `customers?select=id,name&name=like.${encodeURIComponent(prefix)}*`);
    const names: string[] = Array.isArray(found.json) ? found.json.map((c: { name: string }) => c.name) : [];
    for (const name of names) {
      await openList(page);
      await search(page, name);
      const row = rowOf(page, name);
      await expect(row).toBeVisible({ timeout: 20_000 });
      await row.getByRole('button', { name: 'פעולות' }).click();
      await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
      const dlg = page.getByRole('dialog');
      await expect(dlg.getByRole('heading', { name: 'מחיקת לקוח' })).toBeVisible();
      await dlg.getByRole('button', { name: /^מחיקה/ }).click();
      await expect(row).toHaveCount(0, { timeout: 20_000 });
    }
    const left = await rest(page, 'GET', `customers?select=name&name=like.${encodeURIComponent(prefix)}*`);
    expect(left.json, `клиенты ${prefix}* удалены`).toEqual([]);
  } finally {
    await ctx.close();
  }
}

