/** Ожидание ответа GET customer_invites (список или карточка admin). Регистрировать ДО перехода. */
export const invitesLoaded = (page: Page) =>
  page.waitForResponse((r) => /\/rest\/v1\/customer_invites\?/.test(r.url()) && r.request().method() === 'GET' && r.ok(), { timeout: 30_000 });

/** Список admin со статусами после загрузки приглашений. */
export async function openListReady(page: Page) {
  const inv = invitesLoaded(page);
  await openList(page);
  await inv;
}

/** Карточка клиента admin со статусом после загрузки приглашений. */
export async function openCardReady(page: Page, id: string, name: string) {
  const inv = invitesLoaded(page);
  await page.goto(`/customers/${id}`);
  await expect(page.getByRole('heading', { level: 1, name })).toBeVisible({ timeout: 30_000 });
  await inv;
}

/** Тег статуса в карточке (точный текст, чтобы не совпасть с текстом плашки). */
export const cardTag = (page: Page, status: string) => page.getByRole('main').getByText(status, { exact: true });

/** id клиента по имени (REST от текущей сессии). */
export async function customerId(page: Page, name: string) {
  const r = await rest(page, 'GET', `customers?select=id&name=eq.${encodeURIComponent(name)}`);
  expect(r.json, `клиент «${name}»`).toHaveLength(1);
  return r.json[0].id as string;
}
